#!/usr/bin/env node
// deploy/build-deployment-record.mjs
//
// Build one record for an attempt that did NOT reach ci-deploy.mjs — a stale run
// that was skipped, or a transfer/SSH failure where a deployment cannot be
// claimed. The activated/failed path records itself inside ci-deploy.mjs.
//
// Values arrive as flags generated by the workflow; the record is sanitized by
// the same schema used on the host, so unknown fields (tokens, keys, hosts) are
// dropped before anything is displayed.

import fs from "node:fs/promises";
import path from "node:path";
import process from "node:process";

import { DeployError } from "./lib/layout.mjs";
import { sanitizeDeploymentRecord } from "./lib/workflow-records.mjs";

function parseFlags(argv) {
  const flags = {};
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (!arg.startsWith("--")) continue;
    const eq = arg.indexOf("=");
    if (eq !== -1) flags[arg.slice(2, eq)] = arg.slice(eq + 1);
    else {
      flags[arg.slice(2)] = argv[index + 1];
      index += 1;
    }
  }
  return flags;
}

function numberOrNull(value) {
  if (value === undefined || value === null || value === "") return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

try {
  const flags = parseFlags(process.argv.slice(2));
  const out = flags.out && path.resolve(flags.out);
  if (!out) throw new DeployError("--out is required", "INVALID_RECORD");

  const startedAt = flags["started-at"] ?? null;
  const finishedAt = flags["finished-at"] ?? new Date().toISOString();
  const durationMs =
    startedAt && !Number.isNaN(Date.parse(startedAt)) && !Number.isNaN(Date.parse(finishedAt))
      ? Math.max(0, Date.parse(finishedAt) - Date.parse(startedAt))
      : null;

  const record = sanitizeDeploymentRecord({
    runId: flags["run-id"],
    runAttempt: numberOrNull(flags["run-attempt"]),
    workflow: flags.workflow ?? "release.yml",
    event: flags.event ?? "workflow_dispatch",
    target: flags.target ?? "production",
    commit: flags.commit,
    releaseId: flags["release-id"],
    buildId: flags["build-id"],
    builtAt: flags["built-at"] ?? null,
    startedAt,
    finishedAt,
    durationMs,
    requestedBy: flags["requested-by"] ?? null,
    reason: flags.reason ?? null,
    outcome: flags.outcome ?? "failed",
    stage: flags.stage ?? null,
    skipReason: flags["skip-reason"] ?? null,
    artifactHash: flags["artifact-hash"] ?? null,
    health: null,
    rollback: null,
  });

  await fs.mkdir(path.dirname(out), { recursive: true });
  await fs.writeFile(out, `${JSON.stringify(record, null, 2)}\n`, { mode: 0o600 });
  process.stdout.write(`${JSON.stringify({ ok: true, out, outcome: record.outcome, commit: record.commit })}\n`);
} catch (error) {
  const code = error instanceof DeployError ? error.code : "INTERNAL_ERROR";
  process.stdout.write(`${JSON.stringify({ ok: false, code, error: error.message })}\n`);
  process.exitCode = 2;
}
